export interface ConnectorConfig {
  baseId: string;
  tableName: string;
  airtableApiKey: string;
  fetch?: typeof fetch;
}

export interface JotformSubmission {
  email: string;
  first_name?: string;
  last_name?: string;
  phone?: string;
  address?: string;
  [key: string]: unknown;
}

export interface UpdateResult {
  recordId: string;
  updatedFields: string[];
}

const FIELD_MAP: Record<string, string> = {
  first_name: 'First Name',
  last_name: 'Last Name',
  phone: 'Phone',
  address: 'Address',
};

async function handle(payload: JotformSubmission, config: ConnectorConfig): Promise<UpdateResult> {
  const fetchImpl = config.fetch ?? fetch;

  if (!payload.email || typeof payload.email !== 'string') {
    throw new Error('Missing required field: email');
  }

  const email = payload.email;
  const encodedEmail = encodeURIComponent(email);
  const filterFormula = `{email}%3D%22${encodedEmail}%22`;
  const getUrl = `https://api.airtable.com/v0/${config.baseId}/${config.tableName}?filterByFormula=${filterFormula}`;

  const getResponse = await fetchImpl(getUrl, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${config.airtableApiKey}`,
    },
  });

  if (!getResponse.ok) {
    throw new Error(`Airtable GET failed: ${getResponse.status} ${getResponse.statusText} at ${getUrl}`);
  }

  const getData = (await getResponse.json()) as { records: Array<{ id: string; fields: Record<string, unknown> }> };
  if (!getData.records || getData.records.length === 0) {
    throw new Error(`No Airtable record found for email: ${email}`);
  }

  const record = getData.records[0];
  const recordId = record.id;
  const existingFields = record.fields;

  const fieldsToUpdate: Record<string, string> = {};

  for (const [sourceKey, targetKey] of Object.entries(FIELD_MAP)) {
    const sourceValue = payload[sourceKey];
    const existingValue = existingFields[targetKey];

    const isEmpty = existingValue === undefined || existingValue === null || existingValue === '';
    const hasSourceValue = sourceValue !== undefined && sourceValue !== null && sourceValue !== '';

    if (isEmpty && hasSourceValue) {
      fieldsToUpdate[targetKey] = String(sourceValue);
    }
  }

  if (Object.keys(fieldsToUpdate).length === 0) {
    return { recordId, updatedFields: [] };
  }

  const patchUrl = `https://api.airtable.com/v0/${config.baseId}/${config.tableName}/${recordId}`;
  const patchResponse = await fetchImpl(patchUrl, {
    method: 'PATCH',
    headers: {
      Authorization: `Bearer ${config.airtableApiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ fields: fieldsToUpdate }),
  });

  if (!patchResponse.ok) {
    throw new Error(`Airtable PATCH failed: ${patchResponse.status} ${patchResponse.statusText} at ${patchUrl}`);
  }

  return {
    recordId,
    updatedFields: Object.keys(fieldsToUpdate),
  };
}

