  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      baseId: 'appBaseId',
      tableName: 'TableName',
      airtableApiKey: 'test-key',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as JotformSubmission, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.recordId).toBe('recABC123');
