              id: 'rec123',
              fields: {
                'First Name': '',
                'Last Name': 'Doe',
                'Phone': '555-123-4567',
                'Address': '123 Main St',
              },
            },
          ],
        });
      }
      if (req.method === 'PATCH' && req.url.endsWith('/rec123')) {
        expect(req.json).toEqual({ fields: { 'First Name': 'John' } });
        return jsonResponse({
          id: 'rec123',
          fields: {
            'First Name': 'John',
            'Last Name': 'Doe',
            'Phone': '555-123-4567',
            'Address': '123 Main St',
          },
        });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const config: ConnectorConfig = {
      baseId: 'appBaseId',
      tableName: 'TableName',
      airtableApiKey: 'test-key',
      fetch,
    };

    const payload: JotformSubmission = {
      email: 'user@example.com',
      first_name: 'John',
      last_name: 'Doe',
      phone: '555-123-4567',
      address: '123 Main St',
    };

    const result = await handle(payload, config);
    expect(result).toEqual({ recordId: 'rec123', updatedFields: ['First Name'] });
    expect(calls).toHaveLength(2);
